/* === HappiU Base Styles, Campus Font & Photo Sprites === */

@font-face{font-family:Campus;src:url(data:font/woff;base64,) format("woff");font-weight:400;font-display:swap}
@font-face{font-family:Campus;src:url(data:font/woff;base64,) format("woff");font-weight:500;font-display:swap}
@font-face{font-family:Campus;src:url(data:font/woff;base64,) format("woff");font-weight:700;font-display:swap}
:root{--page:#f8f7fc;--surface:#fff;--text:#1d2025;--muted:#4a4d52;--brand:#fc6105;--primary:#ac3600;--soft:#fff0e4;--line:#e2e1e9;--field:#727780;--good:#17633a;--good-bg:#e8f6ed;--wait:#794400;--wait-bg:#fff1cc;--bad:#ad2626;--bad-bg:#fdecec;--info:#215181;--info-bg:#e8f2ff;color-scheme:light}
*{box-sizing:border-box}
body{margin:0;background:var(--page);color:var(--text);font:1rem/1.65 Campus,"Noto Sans Thai",sans-serif}
button,input,textarea,select{font:inherit}
button,select{cursor:pointer}
button{color:inherit}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--primary);outline-offset:3px}
button[disabled]{cursor:default;color:#525760;background:#ececf0;border-color:#dedee4}
h1,h2,h3,p{margin:0}
h1,h2,h3{line-height:1.35}
h2{font-size:1.35rem}
h3{font-size:1.05rem}
.wrap{width:min(1160px,calc(100% - 64px));margin-inline:auto}
.skip{position:absolute;z-index:20;top:8px;left:8px;background:white;color:var(--primary);padding:10px 14px;transform:translateY(-160%)}
.skip:focus{transform:none}
.mast{background:white;border-bottom:1px solid var(--line)}
.bar{min-height:69px;display:flex;align-items:center;gap:17px}
.logo{padding:0;border:0;background:white;min-height:45px}
.wordmark{width:115px;height:36px;display:flex;align-items:center}
.wordmark img{display:block;width:100%;height:100%;object-fit:contain;object-position:left center}
.university{color:var(--muted);border-left:1px solid var(--line);padding-left:17px;font-size:.88rem}
.account{margin-left:auto}
.demo-bar{border-bottom:1px solid var(--line);background:#f0eff5}
.demo-inner{display:flex;gap:16px;align-items:center;justify-content:space-between;min-height:58px}
.demo-label{font-size:.84rem;font-weight:700;white-space:nowrap;color:var(--muted)}
.demo-dot{display:inline-block;width:8px;height:8px;background:var(--primary);border-radius:50%;margin-right:4px}
.roles,.actions,.filters,.pills{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.roles button,.nav-link,.quiet,.reset,.text-button,.chip{min-height:44px;border:0;background:transparent;border-radius:8px;padding:7px 12px;font-size:.89rem;font-weight:700}
.roles button[aria-pressed=true]{background:var(--text);color:white}
.roles button:not([aria-pressed=true]):hover,.quiet:hover,.nav-link:hover,.reset:hover,.text-button:hover{background:#e9e7ed}
.reset{font-weight:400;color:var(--muted)}
.text-button{color:var(--primary);padding-inline:8px;text-align:left}
.app{display:grid;grid-template-columns:190px minmax(0,1fr);gap:34px;min-height:65vh;padding-block:28px 45px}
#nav{align-self:start;display:grid;gap:4px;position:sticky;top:16px}
.nav-title{padding:3px 12px 10px;color:var(--muted);font-size:.8rem}
.nav-link{text-align:left;display:flex;gap:11px;align-items:center;width:100%;min-height:46px;color:#454650}
.nav-link[aria-current=page]{background:var(--soft);color:var(--primary)}
.icon{display:inline-flex;width:19px;height:19px;flex:none;vertical-align:middle}
.icon svg{width:100%;height:100%;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
main{min-width:0}
main:focus{outline:none}
.pagehead{margin-bottom:20px}
.pagehead h1{font-size:clamp(1.65rem,3vw,2.15rem);letter-spacing:-.025em}
.pagehead p{color:var(--muted);margin-top:5px}
.section-head{display:flex;align-items:baseline;justify-content:space-between;gap:14px;margin:24px 0 12px}
.section-head span{color:var(--muted);font-size:.85rem}
.panel,.job-card,.empty,.work-row,.stats>div{border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.panel{padding:20px;margin-bottom:14px}
.panel>h2,.panel>h3{margin-bottom:10px}
.panel p + p{margin-top:6px}
.panel p + .actions,.panel dl + .actions,.panel .list + .actions{margin-top:14px}
.search{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin-bottom:14px}
.search label{position:relative}
.search .icon{position:absolute;top:14px;left:13px;color:var(--muted)}
.search input{padding-left:41px}
input,textarea,select{border:1px solid var(--field);border-radius:8px;color:var(--text);background:white;min-height:44px;width:100%;padding:8px 11px}
textarea{min-height:95px;resize:vertical}
form{margin:0}
.field{display:grid;gap:5px;margin-bottom:13px;font-size:.9rem;font-weight:700}
.field small{color:var(--muted);font-weight:400}
.filter-selects{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:12px}
.filter-selects .field{margin-bottom:0}
.chip{background:white;border:1px solid var(--line);white-space:nowrap}
.chip:hover{border-color:var(--primary)}
.chip[aria-pressed=true]{background:var(--soft);border-color:var(--primary);color:var(--primary)}
.primary,.secondary,.danger{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:44px;padding:7px 15px;border-radius:8px;border:1px solid transparent;font-size:.94rem;font-weight:700;text-align:center}
.primary{background:var(--primary);color:white}
.primary:hover:not(:disabled){background:#8d2d00}
.secondary{background:var(--surface);border-color:var(--primary);color:var(--primary)}
.secondary:hover:not(:disabled){background:var(--soft)}
.danger{background:white;border-color:var(--bad);color:var(--bad)}
.danger:hover:not(:disabled){background:var(--bad-bg)}
.job-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.job-card{overflow:hidden;display:flex;flex-direction:column}
.thumb{aspect-ratio:2.45;overflow:hidden;background:#efeef4}
.thumb img{width:100%;height:100%;object-fit:cover;display:block}
.job-card-body{display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:15px;flex:1}
.job-title{border:0;background:none;text-align:left;font-weight:700;font-size:1.11rem;padding:0;min-height:30px}
.job-title:hover{text-decoration:underline;text-underline-offset:4px}
.job-card .metrics{display:flex;gap:9px 15px;flex-wrap:wrap;font-size:.91rem;margin-bottom:8px}
.job-card .actions{margin-top:auto;width:100%;justify-content:space-between}
.pay{font-variant-numeric:tabular-nums;font-weight:700;color:var(--primary)}
.muted,.helper{color:var(--muted)}
.helper{font-size:.86rem}
.tag{display:inline-flex;align-items:center;gap:4px;vertical-align:middle;padding:3px 8px;font-size:.8rem;border-radius:6px;font-weight:700;background:#efedf3;color:#4c4956;line-height:1.5}
.tag>.icon{width:12px;height:12px}
.tag.good,.callout.good{color:var(--good);background:var(--good-bg)}
.tag.wait,.callout.wait{color:var(--wait);background:var(--wait-bg)}
.tag.bad,.callout.bad{color:var(--bad);background:var(--bad-bg)}
.tag.info,.callout.info{color:var(--info);background:var(--info-bg)}
.callout{padding:11px 13px;font-size:.9rem;background:var(--soft);color:var(--primary);border-radius:8px;margin:10px 0}
.empty{padding:25px;background:var(--surface)}
.empty p{margin:4px 0 10px;color:var(--muted)}
.work-row{margin-bottom:10px;padding:15px;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px}
.work-row p{color:var(--muted);font-size:.91rem;margin-top:3px}
.work-row .actions{justify-content:flex-end}
.labelrow{display:flex;flex-wrap:wrap;align-items:center;gap:7px}
.shift:not(:last-child){margin-bottom:9px}
.shift{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:start;gap:11px;border:1px solid var(--line);background:white;border-radius:9px;padding:10px 13px}
.shift:has(input:checked){border-color:var(--primary);background:var(--soft)}
.shift input{width:19px;height:19px;min-height:0;margin-top:5px;accent-color:var(--primary)}
.shift small{display:block;color:var(--muted)}
dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px 17px;margin:12px 0}
dt{color:var(--muted)}
dd{margin:0;overflow-wrap:anywhere}
.back{margin-bottom:8px}
.two{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.8fr);gap:16px}
.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}
.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:18px}
.stats>div{padding:13px 16px;display:grid;gap:4px}
.stats strong{font-size:1.4rem}
.approval-note{font-size:.86rem;margin-top:4px;color:var(--muted)}
.notice-pop{position:fixed;z-index:4;bottom:18px;left:50%;transform:translateX(-50%);max-width:calc(100% - 28px);background:var(--text);color:white;border-radius:9px;padding:10px 16px;font-weight:700;pointer-events:none}
.notice-pop:empty{display:none}
dialog{background:white;color:var(--text);max-width:min(520px,calc(100% - 30px));border:1px solid var(--line);border-radius:14px;padding:23px}
dialog::backdrop{background:#1d202570}
dialog h2{margin-bottom:10px}
dialog p{margin-bottom:12px}
dialog li+li{margin-top:5px}
dialog .actions{justify-content:flex-end;margin-top:16px}
.footer{border-top:1px solid var(--line);display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding-block:14px;color:var(--muted);font-size:.84rem}
.footer span:first-child{font-weight:700;color:var(--text)}
.footer button{margin-left:auto}
@media(max-width:900px){.wrap{width:calc(100% - 42px)}.app{grid-template-columns:152px minmax(0,1fr);gap:18px}.filter-selects{grid-template-columns:repeat(2,minmax(0,1fr))}.two{grid-template-columns:1fr}}
@media(max-width:640px){.wrap{width:calc(100% - 28px)}.bar{min-height:57px;gap:8px}.wordmark{width:96px}.university{display:none}.demo-inner{min-height:0;display:grid;grid-template-columns:1fr auto;gap:0;padding-top:2px}.demo-label{grid-row:1;grid-column:1}.reset{grid-row:1;grid-column:2;padding-inline:4px}.roles{grid-column:1/-1;gap:5px;padding-bottom:7px}.roles button{padding:7px 9px;min-height:44px}.app{display:block;padding-top:12px;padding-bottom:28px}#nav{display:flex;position:static;overflow-x:auto;gap:5px;margin-bottom:14px;padding:3px}.nav-title{display:none}.nav-link{white-space:nowrap;width:auto;gap:5px;padding:7px 9px;font-size:.82rem}.nav-link .icon{width:16px;height:16px}.hero .overline,.hero p{font-size:.79rem}.hero p{margin-top:6px}.tag{font-size:.76rem}.job-grid{grid-template-columns:1fr}.thumb{aspect-ratio:2.8}.work-row{grid-template-columns:1fr}.work-row .actions{justify-content:flex-start}.panel{padding:14px}.stats{gap:6px}.stats>div{padding:8px}.stats strong{font-size:1.05rem}.stats span{font-size:.8rem}.field-grid{grid-template-columns:1fr}.footer{gap:5px 9px}.footer button{margin-left:0}}

[hidden]{display:none!important}
.nav-phone{display:none}
.sign-out{font-weight:400;color:var(--muted);padding-inline:8px;white-space:nowrap}
.account{max-width:46ch;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.at-login .demo-inner{justify-content:space-between}
.at-login .app{display:block;padding-block:clamp(24px,6vh,72px) 34px;min-height:auto}
.entry{width:min(940px,100%);margin-inline:auto;display:grid;grid-template-columns:1fr 1.05fr;overflow:hidden;background:var(--surface);border:1px solid var(--line);border-radius:18px}
.entry-brand{display:grid;place-items:center;min-height:470px;padding:24px;background:#fff0e4}
.entry-art{width:min(300px,100%);aspect-ratio:1;display:grid;place-items:center}
.entry-art img{width:100%;height:100%;object-fit:contain}
.entry-form{padding:clamp(24px,4vw,49px);display:grid;align-content:center}
.entry-content{min-width:0;display:grid;gap:13px}
.entry-caption{margin:0;color:var(--primary);font-size:.87rem;font-weight:700}
.entry-content h1{font-size:clamp(1.9rem,4.5vw,2.65rem);letter-spacing:-.025em;line-height:1.25}
.entry-description{color:var(--muted);margin-top:-5px}
.login-roles{display:grid;grid-template-columns:.82fr .82fr 1.22fr;gap:6px;margin-top:3px}
.login-roles button{min-width:0;min-height:46px;font-size:.85rem;font-weight:700;border:1px solid var(--line);border-radius:8px;background:#fff;padding:6px 5px}
.login-roles button:hover{border-color:var(--primary)}
.login-roles button[aria-pressed=true]{background:var(--soft);border-color:var(--primary);color:var(--primary)}
.demo-account{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:12px;border:1px solid var(--line);border-radius:10px;padding:12px;background:#faf9fc}
.demo-account>.icon{border-radius:50%;background:var(--soft);color:var(--primary);width:36px;height:36px;padding:8px}
.demo-account strong,.demo-account span{display:block}
.demo-account span:not(.icon){font-size:.84rem;color:var(--muted);overflow-wrap:anywhere}
.entry-actions{display:grid;gap:8px}
.entry-actions button{min-height:48px}
.entry-note{color:var(--muted);font-size:.8rem}
.entry .callout{margin:0}
@media(max-width:640px){
  body:not(.at-login){padding-bottom:calc(67px + env(safe-area-inset-bottom))}
  .bar{gap:7px}
  .account{padding-inline:6px;max-width:min(38vw,190px)}
  .sign-out{font-size:.82rem;padding-inline:4px}
  .at-login .demo-inner{display:flex;min-height:43px}
  .at-login .app{padding-block:18px 22px}
  .entry{display:block;border-radius:14px}
  .entry-brand{min-height:0;height:clamp(122px,24vh,190px);padding:10px 16px}
  .entry-art{width:clamp(103px,29vw,150px);max-height:100%}
  .entry-form{padding:17px 15px 20px}
  .entry-content{gap:11px}
  .entry-content h1{font-size:1.8rem}
  .entry-description{font-size:.91rem}
  .entry-caption{font-size:.8rem}
  .login-roles{gap:5px}
  .login-roles button{font-size:.83rem}
  #nav{display:flex;position:fixed;inset:auto 0 0;z-index:3;height:calc(66px + env(safe-area-inset-bottom));padding:4px max(4px,env(safe-area-inset-right)) calc(4px + env(safe-area-inset-bottom)) max(4px,env(safe-area-inset-left));gap:1px;margin:0;overflow:visible;align-items:stretch;background:white;border-top:1px solid var(--line)}
  .nav-link{flex:1 1 0;min-width:0;display:grid;justify-items:center;align-content:center;gap:3px;white-space:normal;line-height:1.28;text-align:center;padding:2px 1px;font-size:clamp(.68rem,2.9vw,.8rem)}
  .nav-link .icon{width:20px;height:20px}
  .nav-phone{display:block}
  .nav-desktop{display:none}
  body:not(.at-login) .notice-pop{bottom:calc(75px + env(safe-area-inset-bottom))}
}

.student-choices{display:grid;gap:7px}
.student-choice{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px;align-items:center;text-align:left;padding:7px 9px;min-height:54px;border:1px solid var(--line);border-radius:8px;background:#fff}
.student-choice:hover,.student-choice[aria-pressed=true]{border-color:var(--primary)}
.student-choice[aria-pressed=true]{background:var(--soft)}
.student-avatar{display:grid;place-items:center;min-width:44px;min-height:36px;padding-inline:4px;border-radius:8px;background:#efedf3;color:var(--muted);font-size:.72rem;font-weight:700}
.student-choice[aria-pressed=true] .student-avatar{background:white;color:var(--primary)}
.student-choice-copy strong,.student-choice-copy>span{display:block}
.student-choice-copy>span{color:var(--muted);font-size:.79rem;line-height:1.45;overflow-wrap:anywhere}

.filter-selects{grid-template-columns:repeat(2,minmax(0,1fr))}
.time-info .icon{align-self:start;margin-top:3px;color:var(--muted)}
.time-info + .helper{margin-top:10px}
.profile-photo{width:64px;height:64px;object-fit:cover;border:1px solid var(--line);border-radius:50%;margin:10px 0}
.share-fields{border:1px solid var(--line);border-radius:8px;margin:12px 0;padding:8px 12px}
.share-fields legend{font-weight:700;padding-inline:4px}
.share-option{display:flex;gap:9px;align-items:flex-start;min-height:42px;padding-block:7px;font-size:.9rem;overflow-wrap:anywhere}
.share-option input{width:18px;height:18px;min-height:0;flex:none;accent-color:var(--primary)}
.employer-switch{max-width:25rem}
.chat-head{display:flex;gap:9px;flex-wrap:wrap;align-items:center}
.chat-head p{margin:0}
.chat-log{display:flex;flex-direction:column;gap:9px;list-style:none;min-height:100px;max-height:48vh;overflow:auto;margin:14px 0;padding:12px;background:var(--page);border-radius:9px}
.chat-message{align-self:flex-start;max-width:88%;padding:8px 12px;background:white;border:1px solid var(--line);border-radius:9px;overflow-wrap:anywhere}
.chat-message.own{align-self:flex-end;background:var(--soft);border-color:#e0a689}
.chat-message p+p{white-space:pre-wrap;margin-top:2px}

.student-avatar.avatar-photo{padding:0;width:44px;height:44px;border-radius:50%;object-fit:cover;display:block}
.student-profile-identity{display:flex;align-items:center;gap:14px;padding:16px 18px;margin:0 0 16px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.student-profile-identity .student-avatar{width:68px;height:68px;min-width:68px;border-radius:50%}
.student-profile-identity .helper{margin-top:4px}
/* HappiU Stitch design reference */
:root{
  --page:#f8f7fc;
  --surface:#fff;
  --text:#191c21;
  --line:#e2e2eb;
  --soft:#fff0e4;
  --primary:#ac3600;
  --primary-deep:#842700;
  --primary-pressed:#8e2c00;
  --card-border:#ebecf0;
  --shadow:0 2px 10px #23113309;
}
html{scroll-padding-bottom:84px}
.mast,.demo-bar{background:var(--surface)}
.logo{display:flex;align-items:center}
.demo-bar{background:#f1f0f6}
.demo-inner{min-height:52px}
.roles button[aria-pressed=true]{background:var(--soft);color:var(--primary-deep);box-shadow:inset 0 0 0 1px var(--primary)}
.account{display:flex;align-items:center;gap:7px}
.account .student-avatar{width:32px;height:32px;min-width:32px;min-height:32px}
.account>span:last-child{overflow:hidden;text-overflow:ellipsis}
#nav{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:8px;box-shadow:var(--shadow)}
.nav-icon{display:grid;place-items:center}
.nav-link[aria-current=page]{font-weight:800}
body:is([data-role="employer"],[data-role="admin"]) .wrap{width:min(1312px,calc(100% - 64px))}
body:is([data-role="employer"],[data-role="admin"]) .app{grid-template-columns:214px minmax(0,1fr)}
@media(min-width:641px){
  body:is([data-role="employer"],[data-role="admin"]) #nav .nav-link[aria-current=page]{background:var(--soft);color:var(--primary)}
}
.pagehead{margin-bottom:20px}
.pagehead h1{font-weight:800}
.primary{background:var(--primary);border-radius:10px}
.primary:hover:not(:disabled){background:var(--primary-deep)}
.primary:active:not(:disabled){background:var(--primary-pressed)}
.secondary:active:not(:disabled),.chip:active:not(:disabled){background:var(--soft);border-color:var(--primary)}
.primary[disabled]{background:#ececf0;color:#525760}
.secondary,.danger{border-radius:10px}
.panel,.job-card,.work-row,.empty,.stats>div{box-shadow:var(--shadow)}
.panel,.job-card,.work-row,.empty{border-color:var(--card-border);border-radius:14px}
.tag{border-radius:999px;padding-inline:9px;font-size:.77rem}
.entry{border-radius:20px;box-shadow:var(--shadow)}
.entry-brand{min-height:0;padding:30px 24px;align-content:center;justify-items:center;gap:16px;background:#f3f0f8}
.entry-art{width:min(210px,68%);aspect-ratio:1.06}
.entry-intro{text-align:center}
.entry-intro h2{font-size:clamp(1.1rem,3vw,1.8rem);margin-bottom:12px}
.entry-actions .primary{border-radius:999px}
.search{padding:7px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow)}
.search input{border-color:transparent}
.chip{border-radius:999px}
.extra-filters summary{min-height:44px;line-height:44px;color:var(--primary-deep);cursor:pointer;font-size:.9rem;font-weight:700}
.extra-filters summary:focus-visible,.profile-section summary:focus-visible{outline:3px solid var(--primary);outline-offset:3px}
.job-grid{gap:14px}
.job-card{display:flex;flex-direction:column;padding:16px;gap:9px}
.job-company{display:flex;align-items:center;gap:9px;min-width:0}
.job-company>div{flex:1;min-width:0;font-size:.88rem;line-height:1.4}
.job-company .tag{font-size:.7rem}
.job-emblem{width:42px;height:42px;display:grid;place-items:center;border-radius:9px;overflow:hidden;background:var(--soft);color:var(--primary);flex:none}
.job-emblem img{width:100%;height:100%;object-fit:cover}
.job-title{min-height:44px;font-size:1.16rem;line-height:1.4}
.job-card .pay{font-size:1.15rem}
.job-meta{display:flex;align-items:flex-start;gap:8px;color:var(--muted);font-size:.88rem}
.job-meta .icon{margin-top:2px}
.job-card-footer{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:8px;border-top:1px solid var(--line)}
.job-card-footer>.primary{margin-left:auto}
.offer-strip{margin-block:12px;padding:12px 14px;border-inline-start:3px solid var(--primary);background:var(--soft)}
.application-list{display:grid;gap:12px}
.application-card{margin:0}
.application-card .labelrow h3{font-size:1.15rem}
.application-card .helper{margin-top:4px}
.application-timeline{list-style:none;margin:17px 0;padding:0}
.application-timeline>li{display:grid;position:relative;grid-template-columns:28px minmax(0,1fr);gap:11px;align-items:start;padding-bottom:14px}
.application-timeline>li:last-child{padding-bottom:0}
.application-timeline>li:not(:last-child)::before{content:"";position:absolute;inset:28px auto 0 13px;width:2px;background:var(--line)}
.timeline-marker{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:.8rem;background:#eeeef4;color:var(--muted)}
.timeline-marker .icon{width:15px;height:15px}
.application-timeline .done .timeline-marker{background:var(--good-bg);color:var(--good)}
.application-timeline .current .timeline-marker{background:var(--primary);color:white}
.application-timeline .closed .timeline-marker{background:var(--bad-bg);color:var(--bad)}
.application-timeline strong{font-size:.94rem}
.application-timeline li p{font-size:.86rem;color:var(--muted)}
.application-timeline .next strong{color:var(--muted);font-weight:500}
.schedule-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;border:1px solid var(--line);background:var(--surface);padding:5px;border-radius:12px}
.schedule-tabs .chip{border-radius:8px}
.schedule-tabs .chip:not([aria-pressed=true],:hover,:active){border-color:transparent}
.schedule-legend{display:flex;flex-wrap:wrap;gap:16px;margin:14px 0;font-size:.89rem;color:var(--muted)}
.schedule-legend i{display:inline-block;width:10px;height:10px;border-radius:4px;margin-right:4px}
.schedule-legend .job{background:var(--good)}
.schedule-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;margin:0 0 12px}
.schedule-days .chip{padding-inline:2px;border-radius:10px}
.schedule-legend .study{background:linear-gradient(90deg,#32688d 33%,#70458e 33% 66%,#9e4526 66%)}
.schedule-legend .free{background:#f2f3f8;border:1px dashed #797681}
.schedule-week{margin-bottom:16px;background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.schedule-axis,.schedule-week .day:not(.day-selected){display:none}
.schedule-week h2{font-size:1rem;padding:12px 14px;background:#f3f2f8;border-bottom:1px solid var(--line)}
.schedule-week ul{list-style:none;padding:10px;margin:0;display:grid;gap:7px}
.schedule-event{
  display:grid;grid-template-columns:minmax(84px,max-content) minmax(0,1fr);
  align-items:start;gap:2px 10px;padding:8px 9px;border:1px solid transparent;
  border-radius:8px;line-height:1.55;word-break:normal;overflow-wrap:break-word;
  background:var(--slot-bg,#e8f2ff);color:var(--slot-ink,#215181);
}
.schedule-event .slot-time{
  font-variant-numeric:tabular-nums;font-weight:700;font-size:.81rem;
  white-space:nowrap;line-height:1.55;
}
.schedule-event strong{display:block;font-size:.94rem;line-height:1.5}
.slot-details{display:block;font-size:.81rem;line-height:1.5}
.slot-details+.slot-details{margin-top:2px}
.schedule-event.course-0{--slot-bg:#e8f2ff;--slot-ink:#215181}
.schedule-event.course-1{--slot-bg:#fff0da;--slot-ink:#804411}
.schedule-event.course-2{--slot-bg:#f2eafe;--slot-ink:#613b87}
.schedule-event.course-3{--slot-bg:#fbe9f2;--slot-ink:#833359}
.schedule-event.course-4{--slot-bg:#e0f4f3;--slot-ink:#125c62}
.schedule-event.course-5{--slot-bg:#fceae4;--slot-ink:#863b29}
.schedule-event.course-6{--slot-bg:#f0f1d9;--slot-ink:#535b1d}
.schedule-event.job{--slot-bg:#e8f6ed;--slot-ink:#17633a;border-color:#87b79a}
.schedule-event.free{--slot-bg:#f6f5fa;--slot-ink:#514f5d;border-color:#d9d8e2;border-style:dashed}
.schedule-event.free strong{font-weight:500}

@media(min-width:1140px){
  .schedule-days{display:none}
  .schedule-week{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}
  .schedule-week .day:not(.day-selected){display:block}
  .schedule-week .day{min-width:0;border-inline-start:1px solid var(--line)}
  .schedule-week h2,.schedule-axis>strong{
    display:grid;align-items:center;min-height:42px;text-align:center;padding:4px;
    background:#f3f2f8;border-bottom:1px solid var(--line);font-size:.84rem;
  }
  .schedule-week ul{padding:5px}
  .schedule-event{display:block;padding:5px 6px}
  .schedule-event .slot-time{display:block;margin-bottom:2px}
  .schedule-event strong{font-size:.88rem}

  @supports(grid-template-rows:subgrid){
    .schedule-week:not(:has(.day-overlaps)){
      grid-template-columns:55px repeat(7,minmax(0,1fr));
      grid-template-rows:auto var(--schedule-tracks);
    }
    .schedule-week:not(:has(.day-overlaps)) :is(.day,.schedule-axis){
      display:grid;grid-row:1/-1;grid-template-rows:subgrid;
    }
    .schedule-week:not(:has(.day-overlaps)) :is(.day ul,.schedule-axis>div){
      display:grid;grid-row:2/-1;grid-template-rows:subgrid;gap:0;padding:0;
    }
    .schedule-week:not(:has(.day-overlaps)) .schedule-event{
      grid-row:var(--slot-rows);margin:1px 3px;padding:3px 5px;
    }
    .schedule-axis span{
      grid-row:var(--axis-row);display:block;padding:3px 2px;border-top:1px solid var(--line);
      color:var(--muted);text-align:center;font-size:.78rem;font-variant-numeric:tabular-nums;
    }
  }
}
.student-profile-identity{display:grid;justify-items:center;text-align:center;gap:4px;background:linear-gradient(#fff0e4 0%,#fff 68%);padding:23px 16px;overflow-wrap:anywhere}
.student-profile-identity .student-avatar{width:84px;height:84px;min-width:84px;margin-bottom:5px;outline:3px solid white}
.student-profile-identity .tag{margin-top:4px}
.profile-stats>div{text-align:center;justify-items:center;padding:12px 5px;align-content:start}
.profile-stats .icon{color:var(--primary)}
.profile-stats strong{font-size:clamp(.95rem,3vw,1.35rem);overflow-wrap:anywhere}
.profile-stats span:not(.icon){font-size:.79rem;color:var(--muted)}
.profile-section{padding:0 16px}
.profile-section summary{display:flex;align-items:center;gap:13px;cursor:pointer;min-height:62px;padding-block:9px;list-style:none}
.profile-section summary::-webkit-details-marker{display:none}
.profile-section summary::after{content:"";width:7px;height:7px;flex:none;border:solid var(--primary);border-width:0 2px 2px 0;transform:rotate(-45deg);margin-inline-start:auto;margin-inline-end:5px}
.profile-section[open] summary::after{transform:rotate(45deg)}
.profile-section summary>.icon{width:34px;height:34px;padding:7px;border-radius:9px;background:var(--soft);color:var(--primary)}
.profile-section summary small{display:block;color:var(--muted)}
.profile-section[open]{padding-bottom:16px}
.profile-section[open] summary{border-bottom:1px solid var(--line);margin-bottom:12px}
.profile-links,.workspace-tools{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.workspace-tools{align-items:flex-end;justify-content:space-between;margin-bottom:15px}
.workspace-tools .field{margin:0}
.workspace-stats>div{border-left:3px solid #f1b99e}
.income-stats{padding:14px;border-radius:16px;background:var(--primary-deep);color:#fff}
.income-stats>div{border-color:#ffffff3d;background:#ffffff13;color:white;box-shadow:none}

@media(max-width:900px){
  body:is([data-role="employer"],[data-role="admin"]) .wrap{width:calc(100% - 36px)}
  body:is([data-role="employer"],[data-role="admin"]) .app{grid-template-columns:172px minmax(0,1fr)}
}
@media(max-width:640px){
  body:is([data-role="employer"],[data-role="admin"]) .wrap{width:calc(100% - 28px)}
  .mast{position:relative}
  .demo-inner{min-height:44px}
  #nav{border-radius:0;border:0;border-top:1px solid var(--line);padding:4px max(4px,env(safe-area-inset-right)) calc(4px + env(safe-area-inset-bottom)) max(4px,env(safe-area-inset-left));box-shadow:0 -4px 18px #23113312}
  #nav .nav-link[aria-current=page]{background:transparent;color:var(--primary-deep)}
  #nav .nav-link[aria-current=page] .nav-icon{background:var(--soft)}
  #nav .nav-link.nav-desktop-only{display:none}
  .nav-icon{width:37px;height:28px;border-radius:10px}
  .entry-brand{height:auto;min-height:0;gap:5px;padding:12px 14px}
  .entry-art{width:96px}
  .entry-intro h2{margin-bottom:4px}
  .entry-intro .secondary{border:0;background:none;color:var(--primary)}
  .entry-form{padding:16px}
  
  
  .job-card{padding:13px}
  .income-stats{padding:7px}
  .income-stats>div{padding:7px 5px;overflow-wrap:anywhere}
}
@media(prefers-reduced-motion:no-preference){
  button:enabled,summary{
    transition:scale .15s ease-out,background-color .15s ease-out,border-color .15s ease-out;
  }
  button:enabled:active,summary:active{scale:.98;transition-duration:.08s}
  button:is(.chip,.nav-link):enabled:active{scale:.95}
}
/* M1 AI Matching & Student Interests */
.m1-match-wrap{display:flex;flex-direction:column;align-items:flex-start;gap:4px;margin:4px 0}
.m1-match-badge{font-weight:700}
.m1-match-reasons{margin:0;font-size:.82rem;color:var(--muted,#4a4d52);line-height:1.45}
.m1-breakdown{margin-top:14px;padding:14px;border:1px solid var(--card-border,#ebecf0);border-radius:12px;background:var(--surface,#fff)}
.m1-breakdown-head{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:10px}
.m1-factor-list{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:8px}
.m1-factor-row{display:grid;gap:4px}
.m1-factor-meta{display:flex;justify-content:space-between;gap:8px;font-size:.84rem;color:var(--text,#191c21)}
.m1-factor-bar{height:8px;border-radius:999px;background:var(--soft,#fff0e4);overflow:hidden}
.m1-factor-fill{display:block;height:100%;border-radius:999px;background:var(--primary,#ac3600)}
.m1-applicant-match{margin:8px 0;padding:10px 12px;border-radius:10px;background:var(--soft,#fff0e4);border:1px solid #f0d8cc;display:grid;gap:4px}
.m1-applicant-availability{margin:0;font-size:.86rem;color:var(--text,#191c21)}
.m1-interests-fieldset{border:1px solid var(--card-border,#ebecf0);border-radius:12px;padding:12px 14px;margin:12px 0}
.m1-interests-fieldset legend{font-weight:700;font-size:.92rem;padding:0 6px;color:var(--text,#191c21)}
.m1-interests-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px;margin-top:6px}
.m1-interest-chip{display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--card-border,#ebecf0);border-radius:8px;background:var(--surface,#fff);cursor:pointer;min-height:44px}
.m1-interest-chip:has(input:checked){background:var(--soft,#fff0e4);border-color:var(--primary,#ac3600);color:var(--primary,#ac3600);font-weight:600}
.job-grid-ineligible{opacity:.94}
.shift.time-info.is-conflict{border-color:#f3c2c2;background:#fff9f9}
.shift.time-info.is-conflict small{color:var(--bad);font-weight:600}
.shift.time-info.is-open small{color:var(--good)}
/* M2 Multi-Shift & Pay Types */
.pay-type-group{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:12px;align-items:start;margin-bottom:6px}
.pay-type-selector{border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin:0;background:var(--surface)}
.pay-type-selector legend{font-size:.9rem;font-weight:700;padding:0 6px;color:var(--text)}
.pay-type-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.pay-type-option{display:flex;align-items:flex-start;gap:8px;min-height:44px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);cursor:pointer}
.pay-type-option:has(input:checked){border-color:var(--primary);background:var(--soft);color:var(--primary)}
.pay-type-option input{width:18px;height:18px;min-height:0;margin-top:2px;accent-color:var(--primary);flex:none}
.pay-type-option span{display:grid;gap:2px;font-size:.9rem}
.pay-type-option small{color:var(--muted);font-size:.78rem;font-weight:400}
.multi-shift-section{border:1px solid var(--line);border-radius:12px;padding:14px;margin:14px 0;background:var(--surface)}
.multi-shift-section legend{font-size:.95rem;font-weight:700;padding:0 6px;color:var(--text)}
.shift-editor-list{display:grid;gap:10px}
.shift-editor-row{border:1px solid var(--line);border-radius:10px;padding:12px;background:#faf9fd}
.shift-editor-header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}
.shift-remove-btn{min-height:44px;padding:6px 12px;font-size:.86rem}
.shift-editor-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.shift-editor-fields .field{margin-bottom:0}
.shift-editor-actions{display:flex;align-items:center;gap:10px;margin-top:12px}
@media(max-width:900px){.shift-editor-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:640px){.pay-type-group,.pay-type-options,.shift-editor-fields{grid-template-columns:1fr}}
/* M4 Work & Grow Reviews */
.m4-stars{display:inline-flex;align-items:center;gap:4px;font-weight:700;color:#9a4a00;background:#fff6e5;border:1px solid #f3d19e;border-radius:999px;padding:2px 10px;font-size:.86rem;line-height:1.4}
.m4-stars-glyph{letter-spacing:1px;color:#b45309}
.m4-stars-num{color:var(--text,#191c21);font-weight:700}
.m4-review-form{margin-top:12px;padding:12px 14px;border:1px solid var(--card-border,#ebecf0);border-radius:12px;background:var(--soft,#fff0e4)}
.m4-review-form-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:6px;margin-bottom:8px}
.m4-review-form-head strong{font-size:.95rem;color:var(--primary-deep,#842700)}
.m4-review-form-head small{color:var(--muted,#4a4d52);font-size:.82rem}
.m4-review-form .field{margin-bottom:8px}
.m4-review-form .actions{margin-top:8px}
.m4-reviews-summary{margin-top:10px;display:grid;gap:8px}
.m4-review-item{padding:10px 12px;border-radius:10px;border:1px solid var(--line,#e2e2eb);background:var(--surface,#fff)}
.m4-review-item.m4-review-pending{background:var(--page,#f8f7fc);border-style:dashed}
.m4-review-item-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:8px}
.m4-review-item-head strong{font-size:.9rem;color:var(--text,#191c21)}
.m4-review-status-hint{font-size:.84rem;color:var(--muted,#4a4d52)}
.m4-review-comment{margin-top:6px;font-size:.9rem;color:var(--text,#191c21);overflow-wrap:anywhere}
.m4-review-empty-comment{color:var(--muted,#4a4d52);font-style:italic}
.m4-portfolio-section{display:grid;gap:12px}
.m4-portfolio-summary{padding:12px 14px;border-radius:12px;border:1px solid var(--card-border,#ebecf0);background:var(--soft,#fff0e4)}
.m4-portfolio-badge{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px}
.m4-portfolio-badge-label{font-weight:700;color:var(--primary-deep,#842700)}
.m4-portfolio-count{color:var(--muted,#4a4d52);font-size:.84rem}
.m4-portfolio-list{display:grid;gap:10px}
.m4-portfolio-card{padding:12px 14px;border-radius:12px;border:1px solid var(--card-border,#ebecf0);background:var(--surface,#fff);box-shadow:var(--shadow,0 2px 10px #23113309)}
.m4-portfolio-card-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:8px}
.m4-portfolio-card-head h4{margin:0;font-size:1rem}
.m4-portfolio-meta{font-size:.88rem;color:var(--muted,#4a4d52)}
.m4-portfolio-reviews{display:grid;gap:8px}

:root {
  --page: #faf8f5;
  --surface: #fff;
  --text: #25202a;
  --muted: #5f5867;
  --brand: #ff891f;
  --primary: #a83a0b;
  --primary-deep: #803005;
  --primary-pressed: #782604;
  --soft: #fff0de;
  --line: #e9e1da;
  --card-border: #eee3db;
  --field: #8b7b74;
  --shadow: 0 3px 8px #57341d08, 0 12px 30px #57341d09;
}
body {
  background: radial-gradient(ellipse at 70% 0%, #fff3e5 0, transparent 36rem), var(--page);
  font-family: Campus, "Noto Sans Thai", sans-serif;
  line-height: 1.62;
}
h1, h2, h3, h4 { letter-spacing: normal; }
.mast { border-color: #f1e4d6; }
.demo-bar { background: #fff9f2; }
.roles button, .login-roles button { border-radius: 12px; }
.roles button[aria-pressed=true], .login-roles button[aria-pressed=true] {
  background: #fff0dc; color: #8a2c04;
}
#nav { border-color: var(--card-border); }
.nav-link { --tile: #fff0df; --ink: #a13c0d; }
.nav-icon { width: 31px; height: 31px; border-radius: 10px; background: var(--tile); color: var(--ink); }
#nav .nav-link[aria-current=page] .nav-icon { background: #ffdfb5; color: #902b04; }
.nav-link[aria-current=page] { background: #fff3e4; color: #8a2c04; }
.nav-link .icon svg { stroke-width: 1.85; }
.primary:not(:disabled) {
  background: linear-gradient(140deg, #b6450a, #9d2f06);
  color: #fff;
  box-shadow: 0 3px 7px #8c370325;
}
.primary:hover:not(:disabled) { background: #832a06; }
.primary:active:not(:disabled) { background: var(--primary-pressed); }
.primary, .secondary, .danger { border-radius: 12px; }
.panel, .job-card, .work-row, .empty, .stats>div, dialog { border-radius: 18px; }
.entry {
  border-radius: 25px;
  box-shadow: 0 15px 52px #733b1020;
}
.entry-brand { min-height:420px; }
.entry-art { width: min(260px, 85%); }
.entry-logo { display: block; width: clamp(125px, 16vw, 188px); max-height: 58px; object-fit: contain; margin: 0 auto 8px; }
.entry-intro .secondary { border-radius: 999px; }
.student-choice { border-radius: 13px; }
.student-choice[aria-pressed=true] { background: #fff4e6; }
.search { border-radius: 17px; }
.search input { background: #faf7f3; }
.search .icon { color: #8f4b24; }
.filters .chip { display: inline-flex; align-items: center; gap: 6px; padding-inline: 12px; }
.filters .chip .icon { color: #8b502a; width: 16px; height: 16px; }
.chip[aria-pressed=true] { background: #ffead1; color: #7c2b08; border-color: #bc6c35; }
.section-head h2 { display: flex; align-items: center; gap: 8px; }
.section-head h2>.icon { color: #a74310; }
.job-card { padding: 15px; gap: 7px; }
.job-company { gap: 10px; flex-wrap: wrap; }
.job-company>div { min-width: min(7rem, 56%); }
.job-company .tag { font-size: .76rem; }
.job-emblem {
  width: 55px;
  height: 55px;
  border-radius: 15px;
  background: #ffead6;
  color: #9c3d13;
  border: 1px solid #9b5b2426;
}
.job-emblem img { object-fit: contain; }
.job-emblem[data-art="books"] { background: #eaf2ff; color: #245a9b; }
.job-emblem[data-art="event"] { background: #f1e9fc; color: #683c9c; }
.job-emblem[data-art="screen"] { background: #e8f5ef; color: #226749; }
.job-emblem .icon { width: 27px; height: 27px; }
.job-title { font-weight: 800; }
.job-meta .icon { color: #795849; }
.job-card-footer .primary:not(:disabled) {
  color: #893107;
  background: #fff1df;
  border-color: #f2d1a9;
  box-shadow: none;
}
.job-card-footer .primary:hover:not(:disabled) { background: #ffe3c0; border-color: #bc6c35; }
.job-card-footer .primary .icon { width: 15px; height: 15px; }
.income-stats {
  background: linear-gradient(125deg, #993813, #b8480d 60%, #a6390c);
  box-shadow: var(--shadow);
}
.income-stats>div .icon { color: #ffe5bf; }
.student-profile-identity { background: radial-gradient(ellipse at 65% 5%, #ffd9a0, transparent 65%), linear-gradient(#ffedd6, #fff 85%); }
.profile-section:nth-of-type(3n+2) summary>.icon { background: #e9f2ff; color: #245a9b; }
.profile-section:nth-of-type(3n+3) summary>.icon { background: #f1e9fc; color: #683c9c; }
.schedule-tabs, .schedule-week { border-radius: 16px; box-shadow: var(--shadow); }
.schedule-week h2, .schedule-axis>strong { background-color: #edf4ff; }
.callout { border-inline-start: 3px solid currentColor; border-radius: 10px; }
@media (max-width: 640px) {
  .entry-brand { min-height: 0; padding: 14px 14px 9px; }
  .entry-art { width: 132px; }
  .entry-logo { width: 126px; max-height: 36px; margin-bottom: 3px; }
  .entry-form { padding: 17px; }
  .filters { gap: 6px; }
  .filters .chip { padding-inline: 9px; }
  .pagehead { gap: 9px; }
