.chat-topbar { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:8px; }
.chat-topbar h1 { font-size:clamp(1.25rem,2.5vw,1.7rem); }
.chat-shell {
  display:grid;
  grid-template-areas:"rooms context" "rooms thread";
  grid-template-columns:minmax(155px,.72fr) minmax(0,2fr);
  grid-template-rows:auto 1fr;
  gap:12px;
  align-items:start;
}
.chat-pane {
  min-width:0; border:1px solid var(--card-border); border-radius:18px; background:var(--surface);
  box-shadow:var(--shadow);
}
.chat-rooms { grid-area:rooms; padding:0 10px 10px; }
.chat-context { grid-area:context; padding:0 14px; }
.chat-thread { grid-area:thread; overflow:hidden; }
.chat-pane > summary {
  display:flex; align-items:center; justify-content:space-between; gap:6px;
  min-height:49px; font-size:.93rem; cursor:pointer; font-weight:700; list-style:none;
}
.chat-pane > summary::-webkit-details-marker { display:none; }
.chat-pane > summary::after {
  content:""; width:7px; height:7px; margin:0 4px 3px; flex:none;
  border:solid var(--muted); border-width:0 2px 2px 0; transform:rotate(45deg);
}
.chat-pane[open] > summary::after { transform:rotate(-135deg); margin-bottom:-3px; }
.chat-title-label { display:flex; gap:7px; align-items:center; min-width:0; flex:1; }
.chat-room-search { position:relative; display:block; margin-bottom:8px; }
.chat-room-search .icon { position:absolute; inset:12px auto auto 11px; color:var(--muted); }
.chat-room-search input { padding-inline-start:36px; border-color:var(--line); background:#faf7f4; }
.chat-room-list { display:grid; gap:4px; max-height:46vh; overflow:auto; padding:3px; }
.chat-room {
  width:100%; display:flex; align-items:center; gap:8px; min-width:0; min-height:58px;
  border:1px solid transparent; padding:7px; border-radius:12px; background:white; text-align:left;
}
.chat-room:hover { background:#f9f5f1; }
.chat-room[aria-current="true"] { background:#fff2e5; border-color:#edccaa; }
.chat-room-copy { display:grid; gap:1px; min-width:0; flex:1; }
.chat-room-copy>* { min-width:0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; line-height:1.4; }
.chat-room-copy small { color:var(--muted); font-size:.77rem; }
.chat-avatar {
  display:grid; place-items:center; width:38px; height:38px; flex:none; overflow:hidden;
  border-radius:12px; color:#8a3a12; background:#ffead6;
}
.chat-avatar img { width:100%; height:100%; display:block; object-fit:cover; }
.chat-avatar[data-art="books"] { background:#eaf2ff; color:#245a9b; }
.chat-avatar[data-art="books"] img, .chat-avatar[data-art="coffee"] img { object-fit:contain; }
.chat-peer {
  display:flex; align-items:center; gap:10px; min-width:0; background:white;
