}
.chat-message time { display:block; text-align:end; font-size:.73rem; color:var(--muted); }
.chat-empty { margin:auto; text-align:center; padding:15px; color:var(--muted); }
.chat-empty .icon { display:flex; margin:0 auto 7px; color:#a84b1d; width:28px; height:28px; }
.chat-composer { padding:10px; background:white; border-top:1px solid var(--line); }
.chat-compose-controls { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:7px; align-items:end; }
.chat-composer textarea { min-height:46px; max-height:160px; background:#fbf8f5; resize:vertical; }
.chat-composer .primary { min-height:46px; white-space:nowrap; }
.chat-composer [data-form-error]:empty { display:none; }
