/* Shared campus service layout */
:root {
  --page:#f6f5f0;
  --surface:#fff;
  --text:#252420;
  --muted:#56534b;
  --line:#dcd8ce;
  --card-border:var(--line);
  --field:#817b70;
  --soft:#f9ece2;
  --primary:#a23712;
  --primary-deep:#832a0e;
  --shadow:none;
  --popup-shadow:0 6px 22px #32271a20;
}
body { background:var(--page); accent-color:var(--primary); }
::selection { background:#ffd4b9; color:var(--text); }
input,textarea { caret-color:var(--primary); }
input::placeholder,textarea::placeholder { color:var(--muted); opacity:1; }
:focus-visible { outline:2px solid var(--primary); outline-offset:3px; }
main a { text-underline-offset:3px; }
.job-detail-bar {
  display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap;
  gap:8px; margin-bottom:14px; padding-block:7px; border-block:1px solid var(--line);
}
.job-detail-bar .pay { font-size:1.15rem; }
.job-detail-bar a { display:inline-flex; align-items:center; }
#job-shifts { scroll-margin-top:12px; }
.mast { border-color:var(--line); }
.demo-bar { background:var(--page); }
.pagehead { margin-bottom:18px; }
.pagehead h1 { font-size:2rem; font-weight:700; }
.pagehead p { max-width:65ch; }
#nav { background:transparent; border:0; border-radius:0; padding:0; box-shadow:none; }
#nav .nav-icon, #nav .nav-link[aria-current=page] .nav-icon {
  background:transparent; color:currentColor; width:24px; height:24px;
}
.nav-link { border-radius:7px; font-weight:600; }
#nav .nav-link[aria-current=page] { color:var(--primary-deep); background:var(--soft); }
.nav-title { color:var(--muted); font-weight:700; }
.primary,.secondary,.danger,.entry-actions .primary,.entry-actions .secondary { border-radius:7px; }
.primary:not(:disabled) { background:var(--primary); box-shadow:none; }
.primary:hover:not(:disabled) { background:var(--primary-deep); }
.secondary { border-color:var(--field); color:var(--text); }
.secondary:hover:not(:disabled), .text-button:hover { background:var(--soft); }
.secondary:disabled,.primary:disabled { box-shadow:none; }
.panel,.job-card,.work-row,.empty,dialog { border-radius:12px; border-color:var(--line); box-shadow:none; }
.callout { border-inline-start:0; border-radius:7px; }
.hiring-note { border:1px solid var(--line); border-radius:7px; }
.stats:not(.income-stats) { gap:0; background:var(--surface); border-block:1px solid var(--line); }
.stats:not(.income-stats)>div { border:0; border-radius:0; background:transparent; }
.stats:not(.income-stats)>div+div { border-inline-start:1px solid var(--line); }
.stats strong,.overview-totals strong,.pay { font-variant-numeric:tabular-nums; }
.overview-totals>div { background:var(--page); border-radius:6px; }
.overview-totals strong,.job-applicant-count { color:var(--text); }
.overview-stages li { border:0; border-bottom:1px solid var(--line); border-radius:0; }
.work-row { border:0; border-bottom:1px solid var(--line); border-radius:0; margin:0; }
.work-row:first-of-type { border-top:1px solid var(--line); }
.student-profile-identity,.profile-section summary>.icon,
.profile-section:nth-of-type(n) summary>.icon { background:var(--surface); color:var(--text); }
.income-stats { background:var(--surface); border:1px solid var(--line); color:var(--text); }
.income-stats>div { background:var(--page); border-color:var(--line); color:var(--text); }
.income-stats>div .icon { color:var(--primary); }
.income-stats>div :is(span,strong) { color:inherit; }
.entry { border-radius:12px; box-shadow:none; }
.entry-brand { background:var(--soft); }
.entry-art img { filter:none; }
.student-choice { border-radius:8px; }
