:root{--campus-line-art:url("data:image/webp;base64,");--search-elephant:url("data:image/webp;base64,")}
/* Campus illustrations and supporting colors */
:root {
  --peach:#fff0e3;
  --peach-ink:#933304;
  --mint:#e0f2e9;
  --mint-ink:#245d48;
  --sky:#e3effc;
  --sky-ink:#245981;
  --lilac:#eee7fb;
  --lilac-ink:#5c3c86;
  --sun:#fff1c8;
  --sun-ink:#764b12;
  --rose:#fbe8ed;
  --rose-ink:#8c3e58;
  --page:#faf8f4;
  --line:#e6dfd5;
  --primary:#ad3a06;
  --primary-deep:#8d2f06;
}
body {
  --role-tint:var(--peach);
  --role-ink:var(--peach-ink);
  background:linear-gradient(180deg,#fff5e9 0,#faf8f4 380px);
}
body[data-role="employer"] {
  --role-tint:var(--mint);
  --role-ink:var(--mint-ink);
  background:linear-gradient(180deg,#eaf6ef 0,#faf8f4 390px);
}
body[data-role="admin"] {
  --role-tint:var(--sky);
  --role-ink:var(--sky-ink);
  background:linear-gradient(180deg,#edf4ff 0,#faf8f4 390px);
}
.mast { background:#fffdf9; border-bottom-color:#ebe0d1; }
.mast .logo { background:transparent; }
.mast .university {
  display:flex; flex:0 1 auto; align-items:center; gap:8px;
  color:#50483d; font-weight:600; min-width:0;
}
.university img { width:33px; height:33px; object-fit:contain; flex:none; }
.mast .account:not([hidden]) { background:var(--role-tint); color:var(--role-ink); }
.primary:not(:disabled) { background:#ad3a06; color:#fff; }
.primary:hover:not(:disabled) { background:#8d2f06; }

.landing-hero {
  position:relative; isolation:isolate; overflow:hidden;
  grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);
  min-height:280px; gap:10px; padding:clamp(22px,3.2vw,44px);
  background:#fff2df; border:1px solid #efdbc0; border-radius:22px;
}
.landing-copy { position:relative; z-index:1; min-width:0; text-align:left; }
.landing-copy h1 { padding-inline-end:0; }
.landing-copy h1 span, .landing-campus { color:var(--peach-ink); }
.landing-art {
  position:relative; inset:auto; display:grid; justify-self:stretch;
  place-items:center; inline-size:100%; min-height:208px; isolation:isolate;
}
.landing-art::before, .landing-art::after {
  content:""; position:absolute; z-index:-1; pointer-events:none;
}
.landing-art::before {
  width:74%; height:89%; inset:5% 0 auto auto;
  border-radius:56% 44% 44% 56% / 48% 59% 41% 52%; background:#cde9de;
}
.landing-art::after {
  width:45%; height:66%; inset:auto 4% 0 auto;
  border-radius:48% 52% 60% 40% / 44% 57% 43% 56%; background:#ffdb81;
}
.landing-art img.landing-elephant {
  position:relative; z-index:1; width:clamp(145px,19vw,240px); max-width:82%;
  margin-inline-start:34%; align-self:end;
}
body[data-page="landing"] .app { max-width:1160px; }
.landing-jobs { margin-top:24px; }
.landing-list { display:grid; gap:8px; border-top:0; }
.landing-list .landing-job { border:1px solid var(--line); border-inline-start:4px solid var(--category-ink); border-radius:10px; }
.landing-list .landing-job:hover { background:var(--category-bg); }
.landing-identity .helper, .landing-job-next { color:var(--category-ink); }
.landing-job[data-kind], .job-card[data-kind], .chip:is([data-action="landing-kind"],[data-action="filter-kind"]) {
  --category-bg:var(--peach);
  --category-ink:var(--peach-ink);
}
:is(.landing-job,.job-card)[data-kind="campus"], .chip:is([data-action="landing-kind"],[data-action="filter-kind"])[data-id="campus"] {
  --category-bg:var(--mint); --category-ink:var(--mint-ink);
}
:is(.landing-job,.job-card)[data-kind="near"], .chip:is([data-action="landing-kind"],[data-action="filter-kind"])[data-id="near"] {
  --category-bg:var(--sun); --category-ink:var(--sun-ink);
}
:is(.landing-job,.job-card)[data-kind="online"], .chip:is([data-action="landing-kind"],[data-action="filter-kind"])[data-id="online"] {
  --category-bg:var(--lilac); --category-ink:var(--lilac-ink);
}
.landing-jobs-grid .landing-job[data-kind] { border-top-color:var(--category-ink); }
.landing-jobs-grid .landing-job-cover { background:var(--category-bg); color:var(--category-ink); }
.chip:is([data-action="landing-kind"],[data-action="filter-kind"]) {
  color:var(--category-ink); background:var(--category-bg);
}
.chip:is([data-action="landing-kind"],[data-action="filter-kind"])[aria-pressed=true] {
  color:var(--category-ink); background:var(--category-bg); border-color:currentColor;
  box-shadow:inset 0 -2px currentColor;
}
.chip:is([data-action="landing-kind"],[data-action="filter-kind"]) .icon { color:inherit; }

.pagehead {
  --heading-tint:var(--role-tint);
  --heading-ink:var(--role-ink);
  position:relative; isolation:isolate; overflow:hidden;
  padding:14px 16px; border-radius:14px; background:var(--heading-tint);
}
.pagehead[data-page="schedule"] { --heading-tint:var(--sky); --heading-ink:var(--sky-ink); }
.pagehead[data-page="applications"] { --heading-tint:var(--lilac); --heading-ink:var(--lilac-ink); }
.pagehead[data-page="work"] { --heading-tint:var(--mint); --heading-ink:var(--mint-ink); }
.pagehead[data-page="profile"] { --heading-tint:var(--rose); --heading-ink:var(--rose-ink); }
.pagehead[data-page="reports"] { --heading-tint:var(--sun); --heading-ink:var(--sun-ink); }
.pagehead .pagehead-icon { background:#fffaf2; color:var(--heading-ink); }
.pagehead h1 { color:var(--heading-ink); }
.pagehead p { color:#494541; }
body[data-role="student"] .pagehead[data-page="home"] {
  min-height:77px; align-items:center; padding-inline-end:90px;
}
body[data-role="student"] .pagehead[data-page="home"]::after {
  content:""; position:absolute; inset:5px 15px 0 auto; width:68px;
  background:var(--search-elephant) center bottom / contain no-repeat;
  pointer-events:none;
}
body[data-role="student"] .hero { background:#fff2df; }
body[data-role="student"] .hero::before {
  inset:9% 3% 7% auto; width:27%; border-radius:47% 53% 51% 49%; 
  background:#cde9de; mask-image:none;
}
body[data-role="student"] .hero::after {
  inset:auto 18% 4% auto; width:18%; height:64%; border-radius:0; transform:none;
  box-shadow:none; opacity:.48;
  background:var(--campus-line-art) center bottom / contain no-repeat;
}
.hero-art img { filter:none; }
.job-card[data-kind] { border-top:3px solid var(--category-ink); }
.job-card[data-kind] .job-emblem {
  width:40px; height:40px; flex:none; background:var(--category-bg); color:var(--category-ink);
}
.job-card[data-kind] .job-emblem>img { width:94%; height:94%; object-fit:contain; mix-blend-mode:multiply; }
.job-card[data-kind] .job-company { display:flex; align-items:center; gap:9px; }
.job-card[data-kind] .job-company>div { flex:1; }
.job-card[data-kind] .job-meta .icon { color:var(--category-ink); }
#nav .nav-link { --tile:var(--role-tint); --ink:var(--role-ink); }
#nav .nav-link[data-route="schedule"] { --tile:var(--sky); --ink:var(--sky-ink); }
#nav .nav-link[data-route="applications"] { --tile:var(--lilac); --ink:var(--lilac-ink); }
#nav .nav-link[data-route="work"] { --tile:var(--mint); --ink:var(--mint-ink); }
#nav .nav-link[data-route="profile"] { --tile:var(--rose); --ink:var(--rose-ink); }
#nav .nav-link[data-route="reports"] { --tile:var(--sun); --ink:var(--sun-ink); }
#nav .nav-link .nav-icon { background:var(--tile); color:var(--ink); }
body[data-role] #nav .nav-link[aria-current=page] { background:var(--tile); color:var(--ink); }
#nav .nav-link[aria-current=page] .nav-icon { background:var(--ink); color:#fff; }
.stats.workspace-stats:not(.income-stats)>div:nth-child(1), .income-stats>div:nth-child(1) { background:var(--sky); }
.stats.workspace-stats:not(.income-stats)>div:nth-child(2), .income-stats>div:nth-child(2) { background:var(--mint); }
