/* Campus clay direction: landing, recommendations, tutoring */
.landing-hero{
  position:relative;isolation:isolate;overflow:hidden;display:grid;
  grid-template-columns:1fr 1.12fr;align-items:center;gap:0;
  padding:22px 28px 22px clamp(24px,4vw,56px);min-height:390px;
  background:#fff1dc;border:1px solid #f1d2ae;border-radius:32px;
}
.landing-copy{position:relative;z-index:2;padding:22px 0;max-width:520px}
.landing-copy h1{font-size:clamp(2.1rem,3.4vw,3.4rem);line-height:1.35;letter-spacing:-.025em}
.landing-copy h1 span{display:block;color:#b13c10}
.landing-description{color:#665c4e;font-size:1rem;line-height:1.85;max-width:330px;margin-block:20px 24px}
.landing-actions{gap:14px;flex-wrap:wrap}
.landing-actions .primary{border-radius:14px;padding:14px 22px;min-height:50px;background:#b73d13;box-shadow:0 5px 0 #8c2b0b;transition:transform .2s,box-shadow .2s}
.landing-actions .primary:active{transform:translateY(4px);box-shadow:0 1px 0 #8c2b0b}
.landing-actions .text-button{color:#453b30;font-weight:600;min-height:48px}
.landing-art{position:relative;display:grid;place-items:center;height:345px;width:100%;min-width:0;overflow:visible;perspective:900px}
.landing-art::before{content:"";position:absolute;inset:8% 0 0 4%;width:auto;height:auto;border-radius:48% 52% 43% 57%;background:#ffcf91;transform:rotate(-8deg)}
.landing-art::after{display:none}
.landing-art img.landing-elephant{position:relative;inset:auto;width:112%;height:106%;max-width:none;object-fit:contain;object-position:center;filter:drop-shadow(0 20px 18px #ab662923)}
body[data-page="tutors"] .pagehead.pagehead-illustrated{
  position:relative;overflow:hidden;isolation:isolate;grid-template-columns:1fr 1.1fr;min-height:270px;
  padding:26px 34px;border:1px solid #cfdfce;border-radius:28px;background:#eaf2e4;margin-bottom:22px;
}
body[data-page="tutors"] .pagehead h1{font-size:clamp(2rem,3.4vw,3rem);line-height:1.3;color:#234a3f}
body[data-page="tutors"] .pagehead p{font-size:1rem;color:#4d665b;margin-top:12px;line-height:1.8}
body[data-page="tutors"] .pagehead-art{width:100%;height:240px;object-fit:contain;filter:drop-shadow(0 12px 10px #597c5d20)}
body[data-page="tutors"] .tutor-actions{margin-bottom:20px}
body[data-page="tutors"] .tutor-actions .primary{border-radius:12px;padding:12px 20px}
.recommendations{background:transparent;border:0;padding:6px 0 26px;margin-block:4px 20px}
.recommendations>.section-head{margin-bottom:18px}
.recommendations>.section-head h2{font-size:1.5rem;color:#283c33;gap:10px}
.recommendation-grid{gap:20px;align-items:stretch}
.job-card.is-recommended{display:flex;flex-direction:column;padding:0;gap:0;overflow:hidden;border:1px solid #e2e5de;border-radius:24px;background:#fff;box-shadow:0 8px 24px #2c443909;transition:transform .28s,box-shadow .28s,border-color .28s;transform-origin:center bottom}
.is-recommended .job-card-photo{margin:0;border-radius:0;height:174px;aspect-ratio:auto}
.is-recommended .job-card-top{padding:18px 18px 12px;gap:10px}
.is-recommended .job-card-top h3{line-height:1.5}
.is-recommended .job-title{font-size:1.06rem;line-height:1.5}
.is-recommended .job-emblem{width:36px;height:36px;min-width:36px;border-radius:11px}
.is-recommended .job-card-top .helper{margin-top:4px;font-size:.8rem;line-height:1.6}
.is-recommended .recommendation-summary{border:0;background:#f1f5ed;margin:0 18px;padding:12px 14px;border-radius:14px;color:#335443}
.match-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:7px}
.match-heading>span{font-size:.78rem;font-weight:600;color:#45644e;line-height:1.5}
.match-score{font-size:2rem;line-height:1.2;letter-spacing:-.04em;font-variant-numeric:tabular-nums;color:#254f3a}
.match-score small{font-size:.9rem;margin-inline-start:2px;font-weight:500}
.is-recommended .recommendation-summary ul{display:block;margin:0;font-size:.8rem;line-height:1.65}
.is-recommended .recommendation-summary li{background:transparent;border:0;padding:0;margin-top:3px;border-radius:0}
.is-recommended .recommendation-summary>strong{color:#34533f;font-size:.9rem}
.is-recommended .recommendation-summary p{margin:6px 0 0;font-size:.8rem}
.is-recommended .job-card-facts{display:grid;grid-template-columns:1fr;gap:8px;padding:16px 18px;margin:0}
.is-recommended .job-card-facts .job-meta{font-size:.87rem;line-height:1.65;margin:0;grid-column:auto}
.is-recommended .job-card-facts .pay{font-size:1.12rem;font-weight:700;color:#aa3a15;margin:0;grid-row:1}
.is-recommended .job-location-button{font-size:inherit;text-align:start;line-height:1.6;color:#515d55;min-height:30px}
.is-recommended .job-card-footer{margin:0 18px;padding:12px 0;border-top:1px solid #e7e9e2;min-height:58px;margin-top:auto;gap:8px}
.is-recommended .job-card-footer .text-button{min-height:42px;padding:8px 10px;border-radius:10px;color:#a73c17}
.is-recommended .job-card-footer .text-button:hover{background:#fff1e3}
.is-recommended .job-card-badges:empty{display:none}
.tutor-card{transition:transform .25s,box-shadow .25s;border-radius:20px}
@media(hover:hover) and (pointer:fine) and (prefers-reduced-motion:no-preference){
  .job-card.is-recommended:hover{transform:perspective(1000px) translateY(-7px) rotateX(2deg);box-shadow:0 18px 32px #304d3618;border-color:#acc3a5}
  .tutor-card:hover{transform:perspective(1000px) translateY(-5px) rotateX(1deg);box-shadow:0 14px 26px #304d3615}
}
@keyframes campus-float{0%,100%{transform:translateY(0) rotate(-1deg)}50%{transform:translateY(-10px) rotate(1deg)}}
@keyframes campus-reveal{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:no-preference){
  .landing-art img.landing-elephant{animation:campus-float 5.5s ease-in-out infinite}
  body[data-page="tutors"] .pagehead-art{animation:campus-float 6s ease-in-out infinite}
  .recommendation-grid .job-card{animation:campus-reveal .55s ease-out backwards}
  .recommendation-grid .job-card:nth-child(2){animation-delay:.07s}
  .recommendation-grid .job-card:nth-child(3){animation-delay:.14s}
}
