 body[data-page="tutors"] .pagehead.pagehead-illustrated{grid-template-columns:1fr;padding:24px 24px 0;border-radius:24px;gap:0;min-height:0}
 body[data-page="tutors"] .pagehead h1{font-size:2rem}
 body[data-page="tutors"] .pagehead p{font-size:.9rem;margin-top:8px}
 body[data-page="tutors"] .pagehead-art{height:195px;margin-top:8px}
 .recommendation-grid{grid-template-columns:1fr;gap:18px}
 .is-recommended .job-card-photo{height:190px}
