 .is-recommended .job-card-top,.is-recommended .job-card-facts{padding-inline:18px}
 .is-recommended .recommendation-summary,.is-recommended .job-card-footer{margin-inline:18px}
}
@media(prefers-reduced-motion:reduce){
 .landing-art img.landing-elephant,body[data-page="tutors"] .pagehead-art,.recommendation-grid .job-card{animation:none}
 .job-card.is-recommended,.tutor-card,.landing-actions .primary{transition:none;transform:none}
